head.script:
        scwin.onpageload = function () {

        };

        scwin.trigger3_onclick = function(e) {
            var options = {
                "sun" : {
                    "header" : {
                        "color":"#ff0000"
                    },
                    "body" : {
                        "background" : { "background-color":"#ffcccc","opacity":"0.2" },
                        "num" : { "color" : "#ff0000" }
                    }
                },
                "sat" : {
                    "header" : {
                        "color":"#0000ff"
                    },
                    "body" : {
                        "background" : { "background-color":"#ccccff","opacity":"0.2" },
                        "num" : { "color" : "#0000ff" }
                    }
                }
            };
            schdule1.setDayNameStyle(options);
        };

        scwin.trigger4_onclick = function(e) {
            //schdule1.setHeaderBtn({"headerLeftBtn":true});
            //schdule1.setHeaderBtn({"headerTitle":true});
            schdule1.setHeaderBtn({"headerRightBtn":false,"headerLeftBtn":false,"headerTitle":false});
            //schdule1.setHeaderBtn({"headerRightBtn":true});
        };
        scwin.customButton1_onclick = function (e) {
		window.log1 = "custom1 clicked";
            console.log("custom1 clicked");
        };
        scwin.customButton2_onclick = function (e) {
		window.log2 = "custom2 clicked";
            console.log("custom2 clicked");
        };


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('schdule1').children[0].classList.contains('fc-header-toolbar');
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('schdule1').children[0].classList.contains('fc-header-toolbar');
	}	
	scwin.checkVal3 = function() {
		return window.log1 == 'custom1 clicked';
	}		
	scwin.checkVal4 = function() {
		return window.log2 == 'custom2 clicked';
	}		
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('schdule1').querySelectorAll('button')[6].click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('schdule1').querySelectorAll('button')[7].click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
